$config = Get-Content (Join-Path $root 'Config/DefaultGame.ini') -Raw
$failed = $false
if ($header -notmatch 'UPROPERTY\(\)\s+TObjectPtr<UArenaScoreTracker>\s+ScoreTracker') {
    Write-Output 'FAIL: ScoreTracker must be a reflected strong UObject reference.'
    $failed = $true
} else { Write-Output 'PASS: ScoreTracker is a reflected strong UObject reference.' }
$packaging = [regex]::Match($config, '(?ms)^\[/Script/UnrealEd.ProjectPackagingSettings\]\s*(.*?)(?=^\[|\z)').Groups[1].Value
if ($packaging -notmatch '(?m)^\+DirectoriesToAlwaysCook=\(Path="/Game/Data/Palettes"\)\s*$') {
    Write-Output 'FAIL: Packaging must explicitly cook /Game/Data/Palettes.'
    $failed = $true
} else { Write-Output 'PASS: Packaging explicitly cooks /Game/Data/Palettes.' }
if ($failed) { exit 1 }

